mapper.select:
        SELECT U.USER_NO userNo, 
               U.USER_NAME userName, 
               U.EMAIL email, 
               U.PROFILEIMAGE profileImage, 
               R.RANK_NAME rankName, 
               P.POSITION_NAME positionName, 
               O.ORGANIZATION_NAME organizaionName, 
               C.company_Name companyName,
               (SELECT COUNT(1) 
				FROM ADDRBOOKMARK AB 
				WHERE AB.TARGET_NO = U.USER_NO 
				AND AB.USER_NO = #{userNo}) AS isBookmarked
               
        FROM USERS U
        LEFT JOIN TITLE T ON U.USER_NO = T.USER_NO
        LEFT JOIN RANK R ON T.RANK_NO = R.RANK_NO
        LEFT JOIN POSITION P ON T.POSITION_NO = P.POSITION_NO
        LEFT JOIN ORGANIZATION O ON U.USER_NO = O.USER_NO
        LEFT JOIN COMPANY C ON C.COMPANY_NO = U.COMPANY_NO
        
        
        WHERE U.COMPANY_NO = #{companyNo}
        
        
        AND U.USER_NO != #{userNo}
        
        
        
    	
            AND ( u.USER_NAME LIKE #{keyword} 
       OR u.PHONENUMBER LIKE #{keyword} 
       
      
       OR u.USER_NO IN (
           SELECT om.ORGMEMBER_NO 
           FROM ORGANIZATIONMEMBER om
           JOIN ORGANIZATION org ON om.ORGANIZATION_NO = org.ORGANIZATION_NO
           WHERE org.ORGANIZATION_NAME LIKE #{keyword}
       )
       
      
       OR u.USER_NO IN (
           SELECT gm.GRP_MEMBER_NO 
           FROM GROUPSMEMBER gm
           JOIN GROUPS grp ON gm.GROUPS_NO = grp.GROUPS_NO
           WHERE grp.GROUPS_NAME LIKE #{keyword}
       )
       )
        
        
        
            AND U.USER_NO IN (
                SELECT ORGMEMBER_NO 
                FROM ORGANIZATIONMEMBER 
                WHERE ORGANIZATION_NO = #{organizationNo}
            )
        
        
        
        
            AND U.USER_NO IN (
                SELECT GRP_MEMBER_NO 
                FROM GROUPSMEMBER 
                WHERE GROUPS_NO = #{groupsNo}
            )
        
        
        
        
            
                
                
                    AND U.USER_NO IN (
                        SELECT TARGET_NO 
                        FROM ADDRBOOKMARK 
                        WHERE USER_NO = #{userNo}
                    )
                
                
                
                
                    AND U.USER_NO IN (
                        SELECT GRP_MEMBER_NO 
                        FROM GROUPSMEMBER 
                        WHERE GROUPS_NO IN (
                            SELECT GROUPS_NO 
                            FROM groupsMember 
                            WHERE grp_member_NO = #{userNo}
                        )
                    )

SELECT ORGANIZATION_NO organizationNo, ORGANIZATION_NAME organizationName
FROM ORGANIZATION
WHERE COMPANY_NO = #{ companyNo }
